+      }
+      final types = [
+        for (final frame in lines)
+          (frame['type'] ?? frame['event']) as String,
+      ];
+      expect(types.where((t) => t.contains('tool')), isNotEmpty);
+      expect(types, anyElement(contains('turn')));
+    },
+  );
+}
